import { NextRequest, NextResponse } from "next/server";
import { createAdminClient } from "@/lib/supabase/admin";
import { isMagniboxInboundContentLengthTooLarge, MagniboxInboundBodyTooLargeError, readMagniboxBoundedBody, verifyMagniboxInboundSignature } from "@/lib/orbit/transport/inbound";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

/** Signed MTA delivery receipts; queue IDs are generated by the MAGNIBOX MTA. */
export async function POST(request: NextRequest) {
  const secret = process.env.MAGNIBOX_DELIVERY_EVENT_WEBHOOK_SECRET;
  if (process.env.MAGNIBOX_EXTERNAL_MAIL_ENABLED !== "true" || !secret) {
    return NextResponse.json({ error: "Événements de livraison désactivés." }, { status: 503 });
  }
  if (isMagniboxInboundContentLengthTooLarge(request.headers.get("content-length"), 10000)) {
    return NextResponse.json({ error: "Événement trop volumineux." }, { status: 413 });
  }
  let raw: string;
  try {
    raw = await readMagniboxBoundedBody(request.body, 10000);
  } catch (error) {
    if (error instanceof MagniboxInboundBodyTooLargeError) {
      return NextResponse.json({ error: "Événement trop volumineux." }, { status: 413 });
    }
    return NextResponse.json({ error: "Corps invalide." }, { status: 400 });
  }
  if (!verifyMagniboxInboundSignature(raw, request.headers.get("x-magnibox-timestamp"),
    request.headers.get("x-magnibox-signature"), secret)) {
    return NextResponse.json({ error: "Signature invalide." }, { status: 401 });
  }

  let payload: unknown;
  try { payload = JSON.parse(raw); }
  catch { return NextResponse.json({ error: "Événement invalide." }, { status: 400 }); }
  if (!payload || typeof payload !== "object" || Array.isArray(payload)) {
    return NextResponse.json({ error: "Événement invalide." }, { status: 400 });
  }
  const data = payload as Record<string, unknown>;
  if (typeof data.queueId !== "string" || !/^[A-F0-9]{5,20}$/i.test(data.queueId)
    || !["delivered", "bounced", "failed", "deferred"].includes(String(data.event))) {
    return NextResponse.json({ error: "Référence de livraison invalide." }, { status: 400 });
  }

  const state = data.event === "delivered" ? "delivered"
    : data.event === "bounced" ? "bounced"
    : data.event === "failed" ? "failed" : "uncertain";
  const allowed = state === "bounced" ? ["accepted", "sending", "uncertain", "delivered"]
    : state === "uncertain" ? ["accepted", "sending"]
    : ["accepted", "sending", "uncertain"];
  const admin = createAdminClient();
  const updated = await admin.from("orbit_external_messages")
    .update({ status: state, updated_at: new Date().toISOString() })
    .eq("direction", "outgoing")
    .eq("provider_email_id", data.queueId)
    .in("status", allowed);
  if (updated.error) return NextResponse.json({ error: "Mise à jour de livraison indisponible." }, { status: 503 });
  return NextResponse.json({ ok: true }, { status: 202 });
}
